CREATE SCHEMA IF NOT EXISTS infrastructure;
CREATE TABLE IF NOT EXISTS infrastructure.migrations(id TEXT PRIMARY KEY,applied_at TIMESTAMPTZ DEFAULT NOW());
CREATE SCHEMA IF NOT EXISTS profiles;
CREATE TABLE IF NOT EXISTS profiles.users(user_id UUID PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(30) NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE SCHEMA IF NOT EXISTS cinemas;
CREATE TABLE IF NOT EXISTS cinemas.cinemas(id INTEGER PRIMARY KEY,name TEXT NOT NULL,city TEXT NOT NULL,facilities JSONB NOT NULL DEFAULT '[]');
CREATE SCHEMA IF NOT EXISTS movies;
CREATE TABLE IF NOT EXISTS movies.movies(id INTEGER PRIMARY KEY,title TEXT NOT NULL,year INTEGER,genres TEXT[] NOT NULL,duration INTEGER,rating NUMERIC(2,1),poster TEXT NOT NULL,description TEXT NOT NULL,is_new BOOLEAN NOT NULL DEFAULT false,listing_status TEXT NOT NULL DEFAULT 'now_showing');
CREATE SCHEMA IF NOT EXISTS halls;
CREATE TABLE IF NOT EXISTS halls.halls(id INTEGER PRIMARY KEY,cinema_id INTEGER NOT NULL,name TEXT NOT NULL,rows INTEGER NOT NULL DEFAULT 6,columns_count INTEGER NOT NULL DEFAULT 10);
CREATE SCHEMA IF NOT EXISTS seats;
CREATE TABLE IF NOT EXISTS seats.seats(hall_id INTEGER NOT NULL,label TEXT NOT NULL,row_label TEXT NOT NULL,column_number INTEGER NOT NULL,PRIMARY KEY(hall_id,label));
CREATE SCHEMA IF NOT EXISTS showtimes;
CREATE TABLE IF NOT EXISTS showtimes.slots(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,movie_id INTEGER NOT NULL,theatre_id INTEGER NOT NULL,hall_id INTEGER NOT NULL,starts_at TIMESTAMPTZ NOT NULL,auditorium TEXT NOT NULL,price NUMERIC(10,2) NOT NULL,theatre_name TEXT NOT NULL,city TEXT NOT NULL,UNIQUE(movie_id,theatre_id,starts_at));
CREATE SCHEMA IF NOT EXISTS reservations;
CREATE TABLE IF NOT EXISTS reservations.seats(showtime_id INTEGER NOT NULL,seat TEXT NOT NULL,reservation_id UUID NOT NULL,user_id UUID,PRIMARY KEY(showtime_id,seat));
CREATE INDEX IF NOT EXISTS reserved_booking ON reservations.seats(reservation_id);
CREATE SCHEMA IF NOT EXISTS payments;
CREATE TABLE IF NOT EXISTS payments.demo_otps(LIKE booking.demo_otps INCLUDING ALL);
CREATE TABLE IF NOT EXISTS payments.otp_limits(LIKE booking.otp_limits INCLUDING ALL);
CREATE TABLE IF NOT EXISTS payments.transactions(id UUID PRIMARY KEY,user_id UUID NOT NULL,request_id UUID NOT NULL,selection_hash CHAR(64) NOT NULL,showtime_id INTEGER NOT NULL,seats TEXT[] NOT NULL,total NUMERIC(10,2) NOT NULL,status TEXT NOT NULL,payment_reference TEXT NOT NULL,booking_id UUID,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,request_id));
CREATE SCHEMA IF NOT EXISTS tickets;
CREATE TABLE IF NOT EXISTS tickets.records(booking_id UUID PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),email_attempts INTEGER NOT NULL DEFAULT 0,email_requested_at TIMESTAMPTZ,emailed_at TIMESTAMPTZ);
CREATE SCHEMA IF NOT EXISTS notifications;
CREATE TABLE IF NOT EXISTS notifications.deliveries(id UUID PRIMARY KEY,recipient TEXT NOT NULL,subject TEXT NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW(),accepted_at TIMESTAMPTZ);
CREATE SCHEMA IF NOT EXISTS search;
CREATE TABLE IF NOT EXISTS search.documents(movie_id INTEGER PRIMARY KEY,title TEXT NOT NULL,document JSONB NOT NULL,updated_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE booking.reservations ADD COLUMN IF NOT EXISTS failure_reason TEXT;

ALTER TABLE booking.reservations ADD COLUMN IF NOT EXISTS payment_id UUID;
